int jumpSearch(int arr[], int n, int key) {
    int step = (int)sqrt(n);
    int prev = 0;
    while (arr[step < n ? step : n - 1] < key) {
        prev = step;
        step += (int)sqrt(n);
        if (prev >= n) return -1;
    }
    while (arr[prev] < key) {
        prev++;
        if (prev == (step < n ? step : n)) return -1;
    }
    if (arr[prev] == key) return prev;
    return -1;
}

