#define MAX 100

int stack[MAX], top = -1;

void push(int val) {
    if (top == MAX - 1) { printf("Stack Overflow\n"); return; }
    stack[++top] = val;
}

int pop() {
    if (top == -1) { printf("Stack Underflow\n"); return -1; }
    return stack[top--];
}

int peek() {
    return (top == -1) ? -1 : stack[top];
}

