#define V 4
#define E 5

struct Edge { int src, dest, weight; };

int parent[V];

int find(int i) { return parent[i] == i ? i : find(parent[i]); }

void unionSet(int x, int y) { parent[find(x)] = find(y); }

int compare(const void* a, const void* b) {
    return ((struct Edge*)a)->weight - ((struct Edge*)b)->weight;
}

void kruskal(struct Edge edges[]) {
    qsort(edges, E, sizeof(struct Edge), compare);
    for (int i = 0; i < V; i++) parent[i] = i;
    int mstWeight = 0;
    for (int i = 0; i < E; i++) {
        int u = find(edges[i].src), v = find(edges[i].dest);
        if (u != v) {
            printf("Edge %d-%d: %d\n", edges[i].src, edges[i].dest, edges[i].weight);
            mstWeight += edges[i].weight;
            unionSet(u, v);
        }
    }
    printf("MST Weight: %d\n", mstWeight);
}

int main() {
    struct Edge edges[] = {{0,1,10},{0,2,6},{0,3,5},{1,3,15},{2,3,4}};
    kruskal(edges);
