int adj[V][V], visited[V], stack[V], top = -1;

void dfs(int v) {
    visited[v] = 1;
    for (int i = 0; i < V; i++)
        if (adj[v][i] && !visited[i])
            dfs(i);
    stack[++top] = v;
}

void topoSort() {
    for (int i = 0; i < V; i++)
        if (!visited[i]) dfs(i);
    printf("Topological Order: ");
    while (top >= 0)
        printf("%d ", stack[top--]);
    printf("\n");
}

