int isPrime(int n) {
    if (n < 2) return 0;
    if (n == 2) return 1;
    if (n % 2 == 0) return 0;
    for (int i = 3; i <= (int)sqrt(n); i += 2) {
        if (n % i == 0) return 0;
    }
    return 1;
}

int main() {
    for (int i = 1; i <= 30; i++) {
        if (isPrime(i))
            printf("%d is prime\n", i);
    }
    return 0;
}

#include <stdio.h>

// Recursive approach
long long factorialRecursive(int n) {
    if (n == 0 || n == 1) return 1;
    return n * factorialRecursive(n - 1);
}

// Iterative approach
long long factorialIterative(int n) {
    long long result = 1;
    for (int i = 2; i <= n; i++)
        result *= i;
    return result;
}

int main() {
    int n = 10;
    printf("%d! (recursive) = %lld\n", n, factorialRecursive(n));
    printf("%d! (iterative) = %lld\n", n, factorialIterative(n));
    return 0;
}
